const body = $input.first().json.body;
const query = body.query;
const context = body.context || [];
const history = body.conversationHistory || [];
const jobCtx = context[0] || {};

let contextText = `## Job: ${jobCtx.projectName || 'Unknown'} (ID: ${jobCtx.jobId || 'N/A'})\n`;
contextText += `Mode: ${jobCtx.mode || 'N/A'} | Created: ${jobCtx.createdAt || 'N/A'}\n`;

if (jobCtx.approvalStatus) {
  contextText += `Approval: ${jobCtx.approvalStatus}`;
  if (jobCtx.approvedBy) contextText += ` by ${jobCtx.approvedBy}`;
  if (jobCtx.approvedAt) contextText += ` on ${jobCtx.approvedAt}`;
  contextText += '\n';
}

if (jobCtx.summary) {
  contextText += `\n### Summary\n${jobCtx.summary}\n`;
}

if (jobCtx.tasks && jobCtx.tasks.length > 0) {
  contextText += `\n### Tasks (${jobCtx.tasks.length})\n`;
  jobCtx.tasks.forEach(t => {
    contextText += `- [${t.status}] ${t.title} (${t.priority}) - ${t.description}\n`;
  });
}

if (jobCtx.issues && jobCtx.issues.length > 0) {
  contextText += `\n### Issues (${jobCtx.issues.length})\n`;
  jobCtx.issues.forEach(i => {
    contextText += `- ${i.title}: ${i.description}${i.severity ? ' [' + i.severity + ']' : ''}\n`;
  });
}

if (jobCtx.changeOrders && jobCtx.changeOrders.length > 0) {
  contextText += `\n### Change Orders (${jobCtx.changeOrders.length})\n`;
  jobCtx.changeOrders.forEach(c => {
    contextText += `- ${c.title}: ${c.description}\n`;
  });
}

if (jobCtx.transcriptExcerpts && jobCtx.transcriptExcerpts.length > 0) {
  contextText += `\n### Transcript Excerpts (${jobCtx.transcriptExcerpts.length})\n`;
  jobCtx.transcriptExcerpts.slice(0, 30).forEach(t => {
    contextText += `${t.speaker ? '[' + t.speaker + '] ' : ''}${t.text}\n`;
  });
}

let historyText = '';
if (history.length > 0) {
  historyText = '\n## Previous Conversation\n';
  history.forEach(h => {
    historyText += `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}\n`;
  });
}

const systemPrompt = `You are an AI assistant for a construction field notes application. You are in JOB-LEVEL mode.\n\nRules:\n1. ONLY answer based on the provided context data.\n2. If the information is not in the context, say so clearly.\n3. Provide source references when possible.\n4. Be concise but thorough.\n5. Format your response clearly with bullet points where appropriate.`;

const userPrompt = `${contextText}${historyText}\n## Current Question\n${query}`;

return { systemPrompt, userPrompt, query, jobContext: jobCtx };

const body = $input.first().json.body;
const query = body.query;
const context = body.context || [];
const history = body.conversationHistory || [];
const userName = body.userName || 'User';

let contextText = `## Portfolio Overview for ${userName}\n`;
contextText += `Total Jobs: ${context.length}\n\n`;

context.forEach((job, idx) => {
  contextText += `### Job ${idx + 1}: ${job.projectName} (ID: ${job.jobId})\n`;
  contextText += `Mode: ${job.mode} | Created: ${job.createdAt}\n`;
  if (job.approvalStatus) {
    contextText += `Status: ${job.approvalStatus}`;
    if (job.approvedBy) contextText += ` by ${job.approvedBy}`;
    contextText += '\n';
  }
  if (job.summary) {
    contextText += `Summary: ${job.summary.substring(0, 200)}\n`;
  }
  if (job.tasks && job.tasks.length > 0) {
    const openTasks = job.tasks.filter(t => t.status === 'open' || t.status === 'in_progress');
    contextText += `Tasks: ${job.tasks.length} total (${openTasks.length} open)\n`;
    job.tasks.slice(0, 10).forEach(t => {
      contextText += `  - [${t.status}] ${t.title} (${t.priority})\n`;
    });
  }
  if (job.issues && job.issues.length > 0) {
    contextText += `Issues: ${job.issues.length}\n`;
    job.issues.slice(0, 5).forEach(i => {
      contextText += `  - ${i.title}${i.severity ? ' [' + i.severity + ']' : ''}\n`;
    });
  }
  if (job.changeOrders && job.changeOrders.length > 0) {
    contextText += `Change Orders: ${job.changeOrders.length}\n`;
  }
  contextText += '\n';
});

let historyText = '';
if (history.length > 0) {
  historyText = '\n## Previous Conversation\n';
  history.forEach(h => {
    historyText += `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}\n`;
  });
}

const systemPrompt = `You are an AI assistant for a construction field notes application. You are in PORTFOLIO mode.\n\nRules:\n1. ONLY answer based on the provided context data.\n2. When referencing a specific job, always mention the job name and ID.\n3. Identify patterns, trends, and risks across jobs when relevant.\n4. Highlight overdue items, unresolved issues, and scope changes.\n5. Be concise but thorough.\n6. Format your response clearly with bullet points and job references.`;

const userPrompt = `${contextText}${historyText}\n## Current Question\n${query}`;

return { systemPrompt, userPrompt, query, jobCount: context.length };

const input = $input.first().json;
let aiResponse = '';
try {
  aiResponse = input.candidates[0].content.parts[0].text || '';
} catch (e) {
  aiResponse = 'Sorry, I could not generate a response. Please try again.';
}

const prevData = $('Job Context Formatter').first()?.json || {};
const jobCtx = prevData.jobContext || {};
const sources = [];
if (jobCtx.projectName) {
  sources.push({
    projectName: jobCtx.projectName,
    jobId: jobCtx.jobId || '',
    type: 'summary',
    excerpt: (jobCtx.summary || '').substring(0, 100),
    date: jobCtx.createdAt || ''
  });
}

return { answer: aiResponse, sources, mode: 'job', processedAt: new Date().toISOString() };

